    public void AppendBattleLog(
        string category,
        string title,
        string detail)
    {
        WarboardBattleLogEntry entry =
            new WarboardBattleLogEntry
            {
                Sequence =
                    ++battleLogSequence,
                Round = round,
                Faction =
                    activeFaction ?? "",
                Phase =
                    deploymentMode
                    ? "DEPLOYMENT"
                    : phase.ToString()
                        .ToUpper(),
                Category =
                    string.IsNullOrWhiteSpace(
                        category)
                    ? "EVENT"
                    : category,
                Title =
                    string.IsNullOrWhiteSpace(
                        title)
                    ? "Event"
                    : title,
                Detail =
                    detail ?? "",
                Time =
                    System.DateTime.Now
            };

        battleLog.Add(
            entry
        );

        while (battleLog.Count > 300)
        {
            battleLog.RemoveAt(0);
        }
    }

    private void OpenDatasheetForSelection()
    {
        if (selectedModel != null &&
            selectedModel.Squad != null)
        {
            datasheetSquad =
                selectedModel.Squad;
            datasheetModel =
                selectedModel;
        }
        else
        {
            datasheetSquad =
                selectedSquad;
            datasheetModel = null;
        }

        if (datasheetSquad == null)
            return;

        showDatasheet = true;
        datasheetScroll = Vector2.zero;
    }

    private void CloseDatasheet()
    {
        showDatasheet = false;
        datasheetSquad = null;
        datasheetModel = null;
        datasheetScroll = Vector2.zero;
    }

    private void DrawFloatingDatasheetButton()
    {
        if (showDatasheet ||
            selectedSquad == null ||
            deploymentMode ||
            armyImportMode ||
            gameCamera == null)
        {
            return;
        }

        ModelToken anchorModel =
            selectedModel;

        if (anchorModel == null ||
            !anchorModel.IsAlive)
        {
            anchorModel =
                JoinedModels(
                    selectedSquad
                )
                .FirstOrDefault();
        }

        if (anchorModel == null)
            return;

        Vector3 world =
            anchorModel.transform.position +
            Vector3.up * 1.75f;

        Vector3 screen =
            gameCamera.WorldToScreenPoint(
                world
            );

        if (screen.z <= 0f)
            return;

        float x =
            screen.x - 55f;

        float y =
            Screen.height -
            screen.y -
            17f;

        Rect buttonRect =
            new Rect(
                x,
                y,
                110f,
                30f
            );

        if (GUI.Button(
            buttonRect,
            "DATASHEET"))
        {
            OpenDatasheetForSelection();
        }
    }

