    private float DrawDatasheetWeaponSection(
        SquadController squad,
        bool ranged,
        float y,
        float width,
        GUIStyle wrapStyle)
    {
        List<WeaponData> weapons =
            JoinedModels(squad)
                .SelectMany(
                    model =>
                        ranged
                        ? model.RangedWeapons
                        : model.MeleeWeapons
                )
                .Where(
                    weapon =>
                        weapon != null
                )
                .GroupBy(
                    weapon =>
                        string.IsNullOrWhiteSpace(
                            weapon.id
                        )
                        ? weapon.displayName
                        : weapon.id
                )
                .Select(
                    group =>
                        group.First()
                )
                .ToList();

        if (weapons.Count == 0)
        {
            GUI.Label(
                new Rect(
                    0f,
                    y,
                    width,
                    24f
                ),
                "None"
            );

            return y + 28f;
        }

        GUI.Label(
            new Rect(
                0f,
                y,
                width,
                22f
            ),
            "Weapon                         Range    A      Skill   S    AP    D"
        );

        y += 22f;

        foreach (WeaponData weapon
            in weapons)
        {
            string rangeText =
                ranged
                ? weapon.range
                    .ToString("0.#") +
                  "\""
                : "Melee";

            string attacks =
                !string.IsNullOrWhiteSpace(
                    weapon.attacksExpression
                )
                ? weapon.attacksExpression
                : weapon.attacksPerModel
                    .ToString();

            string damage =
                !string.IsNullOrWhiteSpace(
                    weapon.damageExpression
                )
                ? weapon.damageExpression
                : weapon.damage
                    .ToString();

            string row =
                weapon.displayName +
                "    | " +
                rangeText +
                " | " +
                attacks +
                " | " +
                weapon.skill +
                "+ | " +
                weapon.strength +
                " | " +
                weapon.ap +
                " | " +
                damage;

            GUI.Label(
                new Rect(
                    0f,
                    y,
                    width,
                    24f
                ),
                row,
                wrapStyle
            );

            y += 24f;

            string keywordText =
                weapon.keywords != null &&
                weapon.keywords.Length > 0
                ? string.Join(
                    ", ",
                    weapon.keywords
                  )
                : "";

            string raw =
                weapon.rawAbilities ?? "";

            string rules =
                string.Join(
                    " | ",
                    new[]
                    {
                        keywordText,
                        raw
                    }
                    .Where(
                        value =>
                            !string.IsNullOrWhiteSpace(
                                value
                            )
                    )
                    .Distinct()
                    .ToArray()
                );

            if (!string.IsNullOrWhiteSpace(
                rules))
            {
                float ruleHeight =
                    Mathf.Max(
                        22f,
                        wrapStyle.CalcHeight(
                            new GUIContent(rules),
                            width - 12f
                        )
                    );

                GUI.Label(
                    new Rect(
                        12f,
                        y,
                        width - 12f,
                        ruleHeight
                    ),
                    rules,
                    wrapStyle
                );

                y +=
                    ruleHeight +
                    4f;
            }
        }

        return y;
    }

    private float DatasheetContentHeight(
        SquadController squad,
        UnitData data)
    {
        int rangedCount =
            JoinedModels(squad)
                .SelectMany(
                    model =>
                        model.RangedWeapons
                )
                .Where(
                    weapon =>
                        weapon != null
                )
                .Select(
                    weapon =>
                        weapon.id ??
                        weapon.displayName
                )
                .Distinct()
                .Count();

        int meleeCount =
            JoinedModels(squad)
                .SelectMany(
                    model =>
                        model.MeleeWeapons
                )
                .Where(
                    weapon =>
                        weapon != null
                )
                .Select(
                    weapon =>
                        weapon.id ??
                        weapon.displayName
                )
                .Distinct()
                .Count();

        int rules =
            data != null &&
            data.datasheetRules != null
            ? data.datasheetRules.Length
            : 0;

        return
            430f +
            (rangedCount + meleeCount) *
                58f +
            rules *
                95f;
    }

    private void DrawBattlefieldSidePanels(
        float topY)
    {
        if (factions.Count < 2)
            return;

        float width =
            Mathf.Min(
                255f,
                Screen.width * 0.19f
            );

        float height =
            Mathf.Min(
                300f,
                Screen.height -
                    topY -
                    20f
            );

        if (height < 120f)
            return;

        DrawTeamStatusPanel(
            factions[0],
            new Rect(
                15f,
                topY,
                width,
                height
            ),
            ref playerOneSidePanelScroll
        );

        DrawTeamStatusPanel(
            factions[1],
            new Rect(
                Screen.width -
                    width -
                    15f,
                topY,
                width,
                height
            ),
            ref playerTwoSidePanelScroll
        );
    }

    private void DrawTeamStatusPanel(
