    {
        GUI.Box(panel, "");

        GUIStyle title =
            new GUIStyle(
                GUI.skin.label
            );

        title.fontSize = 16;
        title.fontStyle =
            FontStyle.Bold;

        GUI.Label(
            new Rect(
                panel.x + 12f,
                panel.y + 8f,
                panel.width - 24f,
                24f
            ),
            DisplayFactionName(
                faction
            ),
            title
        );

        List<string> reserves =
            ReserveBoxEntries(
                faction
            );

        List<string> dead =
            DeadBoxEntries(
                faction
            );

        float contentHeight =
            54f +
            Mathf.Max(
                1,
                reserves.Count
            ) *
            23f +
            38f +
            Mathf.Max(
                1,
                dead.Count
            ) *
            23f;

        Rect outer =
            new Rect(
                panel.x + 10f,
                panel.y + 38f,
                panel.width - 20f,
                panel.height - 48f
            );

        scroll =
            GUI.BeginScrollView(
                outer,
                scroll,
                new Rect(
                    0f,
                    0f,
                    outer.width - 20f,
                    contentHeight
                )
            );

        float y = 0f;

        GUI.Label(
            new Rect(
                0f,
                y,
                outer.width - 24f,
                22f
            ),
            "IN RESERVES",
            title
        );

        y += 26f;

        if (reserves.Count == 0)
        {
            GUI.Label(
                new Rect(
                    8f,
                    y,
                    outer.width - 32f,
                    22f
                ),
                " - "
            );

            y += 23f;
        }
        else
        {
            foreach (string entry
                in reserves)
            {
                GUI.Label(
                    new Rect(
                        8f,
                        y,
                        outer.width - 32f,
                        22f
                    ),
                    entry
                );

                y += 23f;
            }
        }

        y += 8f;

        GUI.Label(
            new Rect(
                0f,
                y,
                outer.width - 24f,
                22f
            ),
            "DEAD",
            title
        );

        y += 26f;

        if (dead.Count == 0)
        {
            GUI.Label(
                new Rect(
                    8f,
                    y,
                    outer.width - 32f,
                    22f
                ),
                " - "
            );
        }
        else
        {
            foreach (string entry
                in dead)
            {
                GUI.Label(
                    new Rect(
                        8f,
                        y,
                        outer.width - 32f,
                        22f
                    ),
                    entry
                );

                y += 23f;
            }
        }

        GUI.EndScrollView();
    }

    private void DrawMatchScoreboard()
    {
        if (deploymentMode ||
            armyImportMode ||
            factions.Count < 2)
        {
            return;
        }

        const int roundsShown = 5;

        float width =
            Mathf.Min(
                460f,
                Screen.width - 40f
            );

        float height = 250f;

        Rect panel =
            new Rect(
                Screen.width -
                    width -
                    15f,
                15f,
                width,
                height
            );

        GUI.Box(panel, "");

        GUIStyle title =
            new GUIStyle(
                GUI.skin.label
            );

        title.fontSize = 17;
        title.fontStyle =
            FontStyle.Bold;

        GUIStyle centered =
            new GUIStyle(
                GUI.skin.label
            );

        centered.alignment =
            TextAnchor.MiddleCenter;

        centered.fontStyle =
            FontStyle.Bold;

        string p1 =
            factions[0];

        string p2 =
            factions[1];

        GUI.Label(
            new Rect(
                panel.x + 12f,
                panel.y + 8f,
                panel.width - 24f,
                24f
            ),
            "MATCH SCOREBOARD",
            title
        );

        GUI.Label(
            new Rect(
                panel.x + 12f,
                panel.y + 34f,
                panel.width - 24f,
                24f
            ),
            DisplayFactionName(p1) +
            ": " +
            GetCommandPoints(p1) +
            " CP     |     " +
            DisplayFactionName(p2) +
            ": " +
            GetCommandPoints(p2) +
            " CP",
            centered
        );

        float tableY =
            panel.y + 64f;

        float roundWidth = 56f;

        float playerWidth =
            (panel.width -
             roundWidth -
             30f) /
            2f;

        GUI.Label(
            new Rect(
                panel.x + 10f,
                tableY,
                roundWidth,
                22f
            ),
            "ROUND",
            centered
        );

        GUI.Label(
            new Rect(
                panel.x + 10f +
                    roundWidth,
                tableY,
                playerWidth,
                22f
            ),
            DisplayFactionName(p1) +
            "  P / S",
            centered
        );

        GUI.Label(
            new Rect(
                panel.x + 10f +
                    roundWidth +
                    playerWidth,
                tableY,
                playerWidth,
                22f
            ),
            DisplayFactionName(p2) +
            "  P / S",
            centered
        );

        tableY += 24f;

        for (int scoringRound = 1;
             scoringRound <=
                roundsShown;
             scoringRound++)
        {
            GUI.Label(
                new Rect(
                    panel.x + 10f,
                    tableY,
                    roundWidth,
                    21f
                ),
                "R" +
                scoringRound,
                centered
            );

            GUI.Label(
                new Rect(
                    panel.x + 10f +
                        roundWidth,
                    tableY,
                    playerWidth,
                    21f
                ),
                RoundScore(
                    p1,
                    scoringRound,
                    true
                ) +
                " / " +
                RoundScore(
                    p1,
                    scoringRound,
                    false
                ),
                centered
            );

            GUI.Label(
                new Rect(
                    panel.x + 10f +
                        roundWidth +
                        playerWidth,
                    tableY,
                    playerWidth,
                    21f
                ),
                RoundScore(
                    p2,
                    scoringRound,
                    true
                ) +
                " / " +
                RoundScore(
                    p2,
                    scoringRound,
                    false
                ),
                centered
            );

            tableY += 22f;
        }

        int p1Primary =
            TotalScoreType(
                p1,
                true
            );

        int p1Secondary =
            TotalScoreType(
                p1,
                false
            );

        int p2Primary =
            TotalScoreType(
                p2,
                true
            );

        int p2Secondary =
            TotalScoreType(
                p2,
                false
            );

        GUI.Label(
            new Rect(
                panel.x + 10f,
                panel.y + height - 46f,
                panel.width - 20f,
                22f
            ),
            "TOTAL    " +
            DisplayFactionName(p1) +
            ": P " +
            p1Primary +
            " + S " +
            p1Secondary +
            " = " +
            (p1Primary +
             p1Secondary) +
            " VP     |     " +
            DisplayFactionName(p2) +
            ": P " +
            p2Primary +
            " + S " +
            p2Secondary +
            " = " +
            (p2Primary +
             p2Secondary) +
            " VP",
            centered
        );

        GUI.Label(
            new Rect(
                panel.x + 10f,
                panel.y + height - 24f,
                panel.width - 20f,
                18f
            ),
            "P = Primary   |   S = Secondary",
            centered
        );
    }

    private void DrawRuleChoiceWindow()
    {
        if (!showRuleChoiceWindow)
            return;

        float width =
            Mathf.Min(
                680f,
                Screen.width - 60f
            );

        float height =
            Mathf.Min(
                560f,
                Screen.height - 60f
            );

        Rect panel =
            new Rect(
                (Screen.width - width) *
                    0.5f,
                (Screen.height - height) *
                    0.5f,
                width,
                height
            );

        GUI.Box(panel, "");

        GUIStyle title =
            new GUIStyle(
                GUI.skin.label
            );

        title.fontSize = 21;
        title.fontStyle =
            FontStyle.Bold;

        GUIStyle wrap =
            new GUIStyle(
                GUI.skin.label
            );

        wrap.wordWrap = true;

        GUI.Label(
            new Rect(
                panel.x + 20f,
                panel.y + 16f,
                panel.width - 40f,
                30f
            ),
            ruleChoiceTitle,
            title
        );

        float descHeight =
            Mathf.Max(
                48f,
                wrap.CalcHeight(
                    new GUIContent(
                        ruleChoiceDescription
                    ),
                    panel.width - 40f
                )
            );

        GUI.Label(
            new Rect(
                panel.x + 20f,
                panel.y + 54f,
                panel.width - 40f,
                descHeight
            ),
            ruleChoiceDescription,
            wrap
        );

        float listY =
            panel.y +
            64f +
            descHeight;

        Rect outer =
            new Rect(
                panel.x + 20f,
                listY,
                panel.width - 40f,
                panel.y +
                    panel.height -
                    20f -
                    listY
            );

        float contentHeight =
            Mathf.Max(
                outer.height - 2f,
                ruleChoiceOptions.Count *
                    48f
            );

        ruleChoiceScroll =
            GUI.BeginScrollView(
                outer,
                ruleChoiceScroll,
                new Rect(
                    0f,
                    0f,
                    outer.width - 20f,
                    contentHeight
                )
            );

        float y = 0f;

        for (int i = 0;
             i < ruleChoiceOptions.Count;
             i++)
        {
            RuleChoiceOption option =
                ruleChoiceOptions[i];

            if (GUI.Button(
                new Rect(
                    0f,
                    y,
                    outer.width - 26f,
                    40f
                ),
                option.Label))
            {
                System.Action action =
                    option.Action;

                if (action != null)
                    action();

                break;
            }

            y += 48f;
        }

        GUI.EndScrollView();
    }

