        private void DrawXcomAttackDecisionWindow()
    {
        if (interactiveAttack == null)
            return;

        float width =
            Mathf.Min(
                720f,
                Screen.width - 50f
            );

        float height = 430f;

        Rect panel =
            new Rect(
                (Screen.width - width) * 0.5f,
                Mathf.Max(80f, (Screen.height - height) * 0.5f),
                width,
                height
            );

        DrawTintedBox(
            panel,
            new Color(
                0.025f,
                0.03f,
                0.042f,
                0.98f
            )
        );

        GUIStyle heading =
            new GUIStyle(
                GUI.skin.label
            );

        heading.fontSize = 20;
        heading.fontStyle = FontStyle.Bold;

        GUIStyle wrap =
            new GUIStyle(
                GUI.skin.label
            );
        wrap.wordWrap = true;

        GUI.Label(
            new Rect(
                panel.x + 18f,
                panel.y + 14f,
                panel.width - 36f,
                28f
            ),
            "XCOM RESOLUTION - 11E DECISION REQUIRED",
            heading
        );

        GUI.Label(
            new Rect(
                panel.x + 18f,
                panel.y + 50f,
                panel.width - 36f,
                58f
            ),
            interactiveAttack.Attacker.DisplayName +
            "  ->  " +
            interactiveAttack.Target.DisplayName +
            "\n" +
            interactiveAttack.RequirementText,
            wrap
        );

        float y = panel.y + 118f;

        if (interactiveAttack.V48LethalDecisionPending)
        {
            GUI.Label(
                new Rect(panel.x + 18f, y, panel.width - 36f, 42f),
                "LETHAL HITS is optional in 11e. Choose how many Critical Hits automatically wound; the remainder continue to the Wound roll.",
                wrap
            );
            y += 48f;

            if (GUI.Button(
                new Rect(panel.x + 18f, y, 46f, 36f),
                "-"))
            {
                interactiveAttack.V48AdjustLethalDraft(-1);
            }

            GUI.Label(
                new Rect(panel.x + 74f, y + 7f, 210f, 24f),
                interactiveAttack.V48LethalDraft +
                " / " +
                interactiveAttack.V48LethalChoiceMaximum +
                " auto-wound"
            );

            if (GUI.Button(
                new Rect(panel.x + 292f, y, 46f, 36f),
                "+"))
            {
                interactiveAttack.V48AdjustLethalDraft(1);
            }

            if (GUI.Button(
                new Rect(panel.x + panel.width - 258f, y, 240f, 36f),
                "CONFIRM LETHAL HITS"))
            {
                interactiveAttack.V48ConfirmLethalChoice();
                ResumeXcomAttack();
            }

            y += 48f;
        }

        if (interactiveAttack.V48PrecisionDecisionPending)
        {
            GUI.Label(
                new Rect(panel.x + 18f, y, panel.width - 36f, 38f),
                "PRECISION is optional. Select a visible Character allocation group, or resolve these wounds normally.",
                wrap
            );
            y += 42f;

            if (GUI.Button(
                new Rect(panel.x + 18f, y, 46f, 36f),
                "<"))
            {
                interactiveAttack.V48CyclePrecisionCharacter(-1);
            }

            GUI.Label(
                new Rect(panel.x + 74f, y + 7f, 300f, 24f),
                interactiveAttack.V48PrecisionCandidateLabel
            );

            if (GUI.Button(
                new Rect(panel.x + 380f, y, 46f, 36f),
                ">"))
            {
                interactiveAttack.V48CyclePrecisionCharacter(1);
            }

            if (GUI.Button(
                new Rect(panel.x + 438f, y, 120f, 36f),
                "USE PRECISION"))
            {
                interactiveAttack.V48UsePrecisionCharacter();
                ResumeXcomAttack();
            }

            if (GUI.Button(
                new Rect(panel.x + 566f, y, 136f, 36f),
                "NORMAL ALLOCATION"))
            {
                interactiveAttack.V48DeclinePrecision();
                ResumeXcomAttack();
            }

            y += 48f;
        }

        float reactionX = panel.x + 18f;

        if (interactiveAttack.CanUsePartingTheVeil)
        {
            if (GUI.Button(
                new Rect(reactionX, y, 210f, 38f),
                "USE PARTING THE VEIL"))
            {
                interactiveAttack.UsePartingTheVeil();
                ResumeXcomAttack();
            }
            reactionX += 220f;
        }

        if (interactiveAttack.CanUseMacabreResilience)
        {
            if (GUI.Button(
                new Rect(reactionX, y, 225f, 38f),
                "USE MACABRE RESILIENCE"))
            {
                interactiveAttack.UseMacabreResilience();
                ResumeXcomAttack();
            }
            reactionX += 235f;
        }

        if (reactionX > panel.x + 18f)
            y += 48f;

        if (interactiveAttack.CanCommandReroll)
        {
            GUI.Label(
                new Rect(panel.x + 18f, y + 7f, 154f, 24f),
                "COMMAND RE-ROLL:"
            );

            if (GUI.Button(
                new Rect(panel.x + 176f, y, 42f, 36f),
                "<"))
            {
                interactiveAttack.V48CycleCommandRerollDie(-1);
            }

            GUI.Label(
                new Rect(panel.x + 228f, y + 7f, 180f, 24f),
                interactiveAttack.V48SelectedRerollLabel
            );

            if (GUI.Button(
                new Rect(panel.x + 410f, y, 42f, 36f),
                ">"))
            {
                interactiveAttack.V48CycleCommandRerollDie(1);
            }

            if (GUI.Button(
                new Rect(panel.x + panel.width - 258f, y, 240f, 36f),
                "RE-ROLL SELECTED DIE (1 CP)"))
            {
                if (interactiveAttack.UseCommandReroll())
                    ResumeXcomAttack();
            }

            y += 48f;
        }

        if (GUI.Button(
            new Rect(
                panel.x + 18f,
                panel.y + panel.height - 58f,
                260f,
                38f
            ),
            "DECLINE / CONTINUE AUTO"))
        {
            bool complete =
                interactiveAttack.DeclineDecisionAndFastResolve();

            if (complete)
                FinalizeInteractiveAttack();
        }

        GUI.Label(
            new Rect(
                panel.x + 294f,
                panel.y + panel.height - 54f,
                panel.width - 312f,
                34f
            ),
            "v48 preserves player choices that can change the 11e result; routine resolution remains automatic.",
            wrap
        );
    }


    private void DrawInteractiveAttackWindow()
    {
        if (interactiveAttack == null)
            return;

        if (IsXcomMode)
        {
            DrawXcomAttackDecisionWindow();
            return;
        }

        if (interactiveAttack.IsComplete)
        {
            FinalizeInteractiveAttack();
            return;
        }

        InteractiveWeaponVolley volley =
            interactiveAttack.CurrentVolley;

        if (volley == null)
        {
            FinalizeInteractiveAttack();
            return;
        }

        float width =
            Mathf.Min(
                760f,
                Screen.width - 60f
            );

        float height =
            Mathf.Min(
                610f,
                Screen.height - 60f
            );

        Rect panel =
            new Rect(
                (Screen.width - width) *
                    0.5f,
                (Screen.height - height) *
                    0.5f,
                width,
                height
            );

        GUI.Box(panel, "");

        GUIStyle title =
            new GUIStyle(
                GUI.skin.label
            );

        title.fontSize = 22;
        title.fontStyle =
            FontStyle.Bold;

        GUIStyle heading =
            new GUIStyle(
                GUI.skin.label
            );

        heading.fontSize = 16;
        heading.fontStyle =
            FontStyle.Bold;

        GUI.Label(
            new Rect(
                panel.x + 22f,
                panel.y + 16f,
                panel.width - 44f,
                30f
            ),
            interactiveAttack.StageTitle +
            "  -  " +
            volley.weapon.displayName,
            title
        );

        GUI.Label(
            new Rect(
                panel.x + 22f,
                panel.y + 52f,
                panel.width - 44f,
                24f
            ),
            interactiveAttack.Attacker.DisplayName +
            "  ->  " +
            interactiveAttack.Target.DisplayName +
            " | Weapon " +
            interactiveAttack.VolleyNumber +
            "/" +
            interactiveAttack.VolleyCount
        );

        GUI.Label(
            new Rect(
                panel.x + 22f,
                panel.y + 82f,
                panel.width - 44f,
                42f
            ),
            interactiveAttack.RequirementText,
            heading
        );

        IReadOnlyList<int> dice =
            interactiveAttack.CurrentDice;

        if (dice.Count > 0)
        {
            GUI.Label(
                new Rect(
                    panel.x + 22f,
                    panel.y + 126f,
                    150f,
                    22f
                ),
                "Rolled dice:"
            );

            int columns = 10;

            for (int i = 0;
                 i < dice.Count &&
                 i < 40;
                 i++)
            {
                int col =
                    i % columns;

                int row =
                    i / columns;

                DrawDieFace(
                    new Rect(
                        panel.x +
                            22f +
                            col * 54f,
                        panel.y +
                            154f +
                            row * 54f,
                        46f,
                        46f
                    ),
                    dice[i]
                );
            }

            if (dice.Count > 40)
            {
                GUI.Label(
                    new Rect(
                        panel.x + 22f,
                        panel.y + 376f,
                        240f,
                        22f
                    ),
                    "+" +
                    (dice.Count - 40) +
                    " additional dice"
                );
            }
        }
        else
        {
            GUI.Label(
                new Rect(
                    panel.x + 22f,
                    panel.y + 154f,
                    panel.width - 44f,
                    30f
                ),
                "Press the roll button to roll this stage."
            );
        }

        GUI.Label(
            new Rect(
                panel.x + 22f,
                panel.y + height - 174f,
                panel.width - 44f,
                44f
            ),
            interactiveAttack.LastActionText
        );

        Rect mainButton =
            new Rect(
                panel.x + 22f,
                panel.y + height - 118f,
                230f,
                44f
            );

        InteractiveAttackStage stage =
            interactiveAttack.Stage;

        if (stage ==
                InteractiveAttackStage.RollHits ||
            stage ==
                InteractiveAttackStage.RollWounds ||
            stage ==
                InteractiveAttackStage.RollSaves ||
            stage ==
                InteractiveAttackStage.RollDamage)
        {
            string label =
                stage ==
                    InteractiveAttackStage.RollHits
                ? "ROLL HIT DICE"
                : stage ==
                    InteractiveAttackStage.RollWounds
                ? "ROLL WOUND DICE"
                : stage ==
                    InteractiveAttackStage.RollSaves
                ? "ROLL SAVES"
                : "ROLL DAMAGE";

            if (GUI.Button(
                mainButton,
                label))
            {
                interactiveAttack
                    .RollCurrentStage();
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 272f,
                    panel.y + height - 118f,
                    200f,
                    44f
                ),
                "ROLL + NEXT"))
            {
                interactiveAttack
                    .RollAndAdvanceIfNoDecision();

                if (interactiveAttack.IsComplete)
                    FinalizeInteractiveAttack();
            }
        }
        else if (stage ==
            InteractiveAttackStage.ApplyDamage)
        {
            if (GUI.Button(
                mainButton,
                "APPLY DAMAGE"))
            {
                interactiveAttack
                    .RollCurrentStage();
            }
        }
        else
        {
            string label =
                stage ==
                    InteractiveAttackStage.WeaponComplete
                ? (interactiveAttack.VolleyNumber <
                    interactiveAttack.VolleyCount
                    ? "NEXT WEAPON"
                    : "FINISH ATTACK")
                : stage ==
                    InteractiveAttackStage.ReviewHits
                ? "CONTINUE TO WOUNDS"
                : stage ==
                    InteractiveAttackStage.ReviewWounds
                ? "CONTINUE TO SAVES"
                : stage ==
                    InteractiveAttackStage.ReviewSaves
                ? "CONTINUE TO DAMAGE"
                : "APPLY RESULTS";

            if (GUI.Button(
                mainButton,
                label))
            {
                interactiveAttack.Continue();

                if (interactiveAttack.IsComplete)
                    FinalizeInteractiveAttack();
            }
        }

        bool reviewStage =
            stage ==
                InteractiveAttackStage.ReviewHits ||
            stage ==
                InteractiveAttackStage.ReviewWounds ||
            stage ==
                InteractiveAttackStage.ReviewSaves ||
            stage ==
                InteractiveAttackStage.ReviewDamage;

        if (reviewStage)
        {
            GUI.enabled =
                interactiveAttack
                    .CanCommandReroll;

            if (GUI.Button(
                new Rect(
                    panel.x + 272f,
                    panel.y + height - 118f,
                    255f,
                    44f
                ),
                interactiveAttack
                    .CommandRerollButtonText))
            {
                interactiveAttack
                    .UseCommandReroll();
            }

            GUI.enabled = true;

            string rerollFaction =
                stage ==
                    InteractiveAttackStage.ReviewSaves
                ? interactiveAttack
                    .Target
                    .FactionId
                : interactiveAttack
                    .Attacker
                    .FactionId;

            GUI.Label(
                new Rect(
                    panel.x + 540f,
                    panel.y + height - 113f,
                    panel.width - 562f,
                    36f
                ),
                gameObject != null
                ? GetCommandPoints(
                    rerollFaction
                  ) +
                  " CP"
                : ""
            );
        }

        if (interactiveAttack
            .CanUsePartingTheVeil)
        {
            if (GUI.Button(
                new Rect(
                    panel.x + 272f,
                    panel.y + height - 118f,
                    220f,
                    44f
                ),
                "PARTING THE VEIL (2 CP)"))
            {
                interactiveAttack
                    .UsePartingTheVeil();
            }
        }

        if (interactiveAttack
            .CanUseMacabreResilience)
        {
            if (GUI.Button(
                new Rect(
                    panel.x +
                        (interactiveAttack.CanUsePartingTheVeil
                            ? 500f
                            : 272f),
                    panel.y + height - 118f,
                    interactiveAttack.CanUsePartingTheVeil
                        ? 220f
                        : 255f,
                    44f
                ),
                "MACABRE RESILIENCE (1 CP)"))
            {
                interactiveAttack
                    .UseMacabreResilience();
            }
        }

        bool decisionAvailable =
            interactiveAttack
                .HasMeaningfulDecision;

        string fastLabel =
            (interactiveAttack
                .CanUsePartingTheVeil ||
             interactiveAttack
                .CanUseMacabreResilience)
            ? "DECLINE REACTION + FAST"
            : decisionAvailable
                ? "DECLINE RE-ROLL + FAST"
                : "FAST RESOLVE TO DECISION";

        if (GUI.Button(
            new Rect(
                panel.x + 22f,
                panel.y + height - 60f,
                300f,
                38f
            ),
            fastLabel))
        {
            bool completed =
                decisionAvailable
                ? interactiveAttack
                    .DeclineDecisionAndFastResolve()
                : interactiveAttack
                    .FastResolveUntilDecision();

            if (completed)
            {
                FinalizeInteractiveAttack();
            }
            else if (interactiveAttack != null &&
                     interactiveAttack
                        .HasMeaningfulDecision)
            {
                status =
                    "Fast Resolve paused for a real decision: " +
                    interactiveAttack.StageTitle +
                    ".";
            }
        }

        GUI.Label(
            new Rect(
                panel.x + 336f,
                panel.y + height - 58f,
                panel.width - 358f,
                38f
            ),
            "Fast Resolve still rolls every die; it stops when a CP re-roll choice exists."
        );
    }

