    private void DrawMissionBattlefieldPreview(
        Rect rect,
        MissionBattlefieldDefinition definition)
    {
        // WARBOARD_V54_BRIGHT_MISSION_PREVIEW
        if (definition == null)
            return;

        DrawTintedBox(
            rect,
            new Color(
                0.10f,
                0.12f,
                0.15f,
                1f
            )
        );

        Rect board =
            new Rect(
                rect.x + 8f,
                rect.y + 26f,
                rect.width - 16f,
                rect.height - 34f
            );

        DrawTintedBox(
            board,
            new Color(
                0.43f,
                0.47f,
                0.45f,
                1f
            )
        );

        System.Func<Vector3, Vector2> toGui =
            world =>
                new Vector2(
                    board.x +
                    (world.x /
                     BoardWidth +
                     0.5f) *
                    board.width,
                    board.y +
                    (0.5f -
                     world.z /
                     BoardDepth) *
                    board.height
                );

        foreach (MissionTerrainSpec terrain
            in definition.Terrain)
        {
            Vector2 centre =
                toGui(
                    terrain.Position
                );

            float w =
                terrain.Size.x /
                BoardWidth *
                board.width;

            float h =
                terrain.Size.z /
                BoardDepth *
                board.height;

            DrawTintedBox(
                new Rect(
                    centre.x - w * 0.5f,
                    centre.y - h * 0.5f,
                    w,
                    h
                ),
                terrain.Trait ==
                    TerrainTrait.Blocking
                ? new Color(
                    0.28f,
                    0.30f,
                    0.34f,
                    0.95f
                  )
                : new Color(
                    0.36f,
                    0.44f,
                    0.35f,
                    0.95f
                  )
            );
        }

        foreach (MissionObjectiveSpec objective
            in definition.Objectives)
        {
            Vector2 centre =
                toGui(
                    objective.Position
                );

            DrawTintedBox(
                new Rect(
                    centre.x - 5f,
                    centre.y - 5f,
                    10f,
                    10f
                ),
                new Color(
                    0.95f,
                    0.80f,
                    0.16f,
                    1f
                )
            );
        }

        GUI.Label(
            new Rect(
                rect.x + 8f,
                rect.y + 4f,
                rect.width - 16f,
                20f
            ),
            definition.DisplayName +
            "  |  Layout " +
            definition.LayoutLabel
        );
    }

    private void DrawMissionSetupPlayer(
        Rect rect,
        int index,
        ForceDisposition own,
        ForceDisposition opponent,
        MissionSecondaryMode secondaryMode)
    {
        GUIStyle heading =
            new GUIStyle(
                GUI.skin.label
            );

        heading.fontSize = 17;
        heading.fontStyle =
            FontStyle.Bold;

        GUIStyle small =
            new GUIStyle(
                GUI.skin.label
            );

        small.fontSize = 11;
        small.wordWrap = true;

        string player =
            index == 0
            ? playerOneRosterLabel
            : playerTwoRosterLabel;

        string faction =
            factions.Count > index
            ? factions[index]
            : "";

        GUI.Label(
            new Rect(
                rect.x + 14f,
                rect.y + 10f,
                rect.width - 28f,
                24f
            ),
            player,
            heading
        );

        GUI.Label(
            new Rect(
                rect.x + 14f,
                rect.y + 40f,
                rect.width - 28f,
                22f
            ),
            "Force Disposition: " +
            MissionRegistry.Display(
                own
            )
        );

        GUI.Label(
            new Rect(
                rect.x + 14f,
                rect.y + 68f,
                rect.width - 28f,
                44f
            ),
            "Primary: " +
            MissionRegistry.ResolvePrimary(
                own,
                opponent
            ),
            heading
        );

        if (aeldariRules != null &&
