    private void DrawMissionPanel()
    {
        if (!showMissionPanel ||
            missionSystem == null)
        {
            return;
        }

        float width =
            Mathf.Min(
                820f,
                Screen.width - 40f
            );

        float height =
            Mathf.Min(
                610f,
                Screen.height - 90f
            );

        Rect panel =
            new Rect(
                18f,
                66f,
                width,
                height
            );

        DrawTintedBox(
            panel,
            new Color(
                0.025f,
                0.03f,
                0.042f,
                0.98f
            )
        );

        GUIStyle heading =
            new GUIStyle(
                GUI.skin.label
            );

        heading.fontSize = 18;
        heading.fontStyle =
            FontStyle.Bold;

        GUI.Label(
            new Rect(
                panel.x + 16f,
                panel.y + 12f,
                panel.width - 32f,
                28f
            ),
            "MISSION INFO / RULES  -  ROUND " +
            round +
            "  |  LAYOUT " +
            missionLayoutIndex,
            heading
        );

        if (factions.Count >= 2)
        {
            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 46f,
                    panel.width - 32f,
                    50f
                ),
                DisplayFactionName(
                    factions[0]
                ) +
                ": " +
                missionSystem
                    .MissionStateSummary(
                        factions[0]
                    ) +
                "\n" +
                DisplayFactionName(
                    factions[1]
                ) +
                ": " +
                missionSystem
                    .MissionStateSummary(
                        factions[1]
                    )
            );
        }

        MissionPlayerState activeState =
            missionSystem.State(
                activeFaction
            );

        if (activeState == null)
            return;

        Rect operations =
            new Rect(
                panel.x + 16f,
                panel.y + 110f,
                panel.width - 32f,
                254f
            );

        DrawTintedBox(
            operations,
            new Color(
                0.05f,
                0.055f,
                0.07f,
                1f
            )
        );

        GUI.Label(
            new Rect(
                operations.x + 12f,
                operations.y + 10f,
                operations.width - 24f,
                24f
            ),
            ActiveFactionDisplayName() +
            "  -  " +
            activeState.PrimaryMission,
            heading
        );

        float y =
            operations.y + 44f;

        DrawMissionCounterRow(
            operations,
            ref y,
            MissionRegistry.OperationLabel(
                activeState.PrimaryMission
            ),
            activeState.PersistentMarks,
            () =>
                missionSystem
                    .IncrementPersistentMarks(
                        activeFaction,
                        -1
                    ),
            () =>
                missionSystem
                    .IncrementPersistentMarks(
                        activeFaction,
                        1
                    )
        );

        DrawMissionCounterRow(
            operations,
            ref y,
            "Operation markers",
            activeState.OperationMarkers,
            () =>
                missionSystem
                    .IncrementOperationMarkers(
                        activeFaction,
                        -1
                    ),
            () =>
                missionSystem
                    .IncrementOperationMarkers(
                        activeFaction,
                        1
                    )
        );

        DrawMissionCounterRow(
            operations,
            ref y,
            MissionRegistry.TurnActionLabel(
                activeState.PrimaryMission
            ),
            activeState.TurnActionCompletions,
            () =>
                missionSystem
                    .IncrementTurnActions(
                        activeFaction,
                        -1
                    ),
            () =>
                missionSystem
                    .IncrementTurnActions(
                        activeFaction,
                        1
                    )
        );

        DrawMissionCounterRow(
            operations,
            ref y,
            MissionRegistry.TurnBonusLabel(
                activeState.PrimaryMission
            ),
            activeState.TurnBonusCompletions,
            () =>
                missionSystem
                    .IncrementTurnBonus(
                        activeFaction,
                        -1
                    ),
            () =>
                missionSystem
                    .IncrementTurnBonus(
                        activeFaction,
                        1
                    )
        );

        DrawMissionCounterRow(
            operations,
            ref y,
            MissionRegistry.SpecialEventLabel(
                activeState.PrimaryMission
            ),
            activeState.TurnSpecialEvents,
            () =>
                missionSystem
                    .IncrementTurnSpecialEvents(
                        activeFaction,
                        -1
                    ),
            () =>
                missionSystem
                    .IncrementTurnSpecialEvents(
                        activeFaction,
                        1
                    )
        );

        DrawMissionCounterRow(
            operations,
            ref y,
            MissionRegistry.BonusLabel(
                activeState.PrimaryMission
            ),
            activeState.PersistentBonusMarks,
            () =>
                missionSystem
                    .IncrementBonusMarks(
                        activeFaction,
                        -1
                    ),
            () =>
                missionSystem
                    .IncrementBonusMarks(
                        activeFaction,
                        1
                    )
        );

        Rect secondary =
            new Rect(
                panel.x + 16f,
                panel.y + 378f,
                panel.width - 32f,
                panel.height - 394f
            );

        DrawTintedBox(
            secondary,
            new Color(
                0.05f,
                0.055f,
                0.07f,
                1f
            )
        );

        GUI.Label(
            new Rect(
                secondary.x + 12f,
                secondary.y + 10f,
                secondary.width - 24f,
                24f
            ),
            "SECONDARIES  -  " +
            activeState.SecondaryMode
                .ToString()
                .ToUpper(),
            heading
        );

        if (activeState.SecondaryMode ==
            MissionSecondaryMode.Fixed)
        {
            DrawFixedSecondaryControls(
                secondary,
                activeState
            );
        }
        else
        {
            DrawTacticalSecondaryControls(
                secondary,
                activeState
            );
        }
    }

    private void DrawMissionCounterRow(
        Rect panel,
        ref float y,
        string label,
        int value,
        System.Action minus,
        System.Action plus)
    {
        GUI.Label(
            new Rect(
                panel.x + 12f,
                y,
                panel.width - 150f,
                24f
            ),
            label +
            ": " +
            value
        );

        if (GUI.Button(
            new Rect(
                panel.x +
                    panel.width -
                    126f,
                y - 2f,
                48f,
                26f
            ),
            "-"))
        {
            minus();
        }

        if (GUI.Button(
            new Rect(
                panel.x +
                    panel.width -
                    66f,
                y - 2f,
                48f,
                26f
            ),
            "+"))
        {
            plus();
        }

        y += 32f;
    }

    private void DrawTacticalSecondaryControls(
        Rect rect,
        MissionPlayerState state)
    {
        if (GUI.Button(
            new Rect(
                rect.x + 12f,
                rect.y + 76f,
                105f,
                30f
            ),
            "DRAW"))
        {
            status =
                missionSystem.DrawSecondary(
                    activeFaction
                );
        }

        float y =
            rect.y + 116f;

        for (int i = 0;
             i < state.SecondaryHand.Count;
             i++)
        {
            int captured = i;

            GUI.Label(
                new Rect(
                    rect.x + 12f,
                    y,
                    rect.width - 340f,
                    28f
                ),
                state.SecondaryHand[i]
            );

            if (GUI.Button(
                new Rect(
                    rect.x +
                        rect.width -
                        314f,
                    y - 2f,
                    72f,
                    28f
                ),
                "+3 VP"))
            {
                int award =
                    missionSystem.ScoreSecondary(
                        activeFaction,
                        captured,
                        3,
                        round
                    );

                status =
                    award > 0
                    ? "Secondary scored +" +
                      award +
                      " VP."
                    : "Secondary score capped or unavailable.";
            }

            if (GUI.Button(
                new Rect(
                    rect.x +
                        rect.width -
                        234f,
                    y - 2f,
                    72f,
                    28f
                ),
                "+5 VP"))
            {
                int award =
                    missionSystem.ScoreSecondary(
                        activeFaction,
                        captured,
                        5,
                        round
                    );

                status =
                    award > 0
                    ? "Secondary scored +" +
                      award +
                      " VP."
                    : "Secondary score capped or unavailable.";
            }

            if (GUI.Button(
                new Rect(
                    rect.x +
                        rect.width -
                        154f,
                    y - 2f,
                    130f,
                    28f
                ),
                "DISCARD"))
            {
                status =
                    missionSystem
                        .DiscardSecondary(
                            activeFaction,
                            captured
                        );

                break;
            }

            y += 36f;
        }

        GUI.Label(
            new Rect(
                rect.x + 12f,
                rect.y +
                    rect.height -
                    34f,
                rect.width - 24f,
                26f
            ),
            "Deck: " +
            state.SecondaryDeck.Count +
            "  |  Hand: " +
            state.SecondaryHand.Count +
            "/2  |  secondary scoring is capped at 15 VP per round / 45 VP total."
        );
    }

    private void DrawFixedSecondaryControls(
        Rect rect,
        MissionPlayerState state)
    {
        float y =
            rect.y + 80f;

        for (int i = 0;
             i < state.FixedSecondaries.Count;
             i++)
        {
            int captured = i;

            GUI.Label(
                new Rect(
                    rect.x + 12f,
                    y,
                    rect.width - 330f,
                    28f
                ),
                state.FixedSecondaries[i]
            );

            if (GUI.Button(
                new Rect(
                    rect.x +
                        rect.width -
                        314f,
                    y - 2f,
                    82f,
                    28f
                ),
                "NEXT"))
            {
                missionSystem
                    .CycleFixedSecondary(
                        activeFaction,
                        captured
                    );
            }

            if (GUI.Button(
                new Rect(
                    rect.x +
                        rect.width -
                        222f,
                    y - 2f,
                    82f,
                    28f
                ),
                "+3 VP"))
            {
                missionSystem.ScoreSecondary(
                    activeFaction,
                    captured,
                    3,
                    round
                );
            }

            if (GUI.Button(
                new Rect(
                    rect.x +
                        rect.width -
                        130f,
                    y - 2f,
                    106f,
                    28f
                ),
                "+5 VP"))
            {
                missionSystem.ScoreSecondary(
                    activeFaction,
                    captured,
                    5,
                    round
                );
            }

            y += 38f;
        }

        GUI.Label(
            new Rect(
                rect.x + 12f,
                rect.y +
                    rect.height -
                    44f,
                rect.width - 24f,
                36f
            ),
            "Each Fixed secondary is capped at 20 VP; total secondary scoring is also capped at 15 VP per round / 45 VP per game."
        );
    }

