                battleLogScroll,
                new Rect(
                    0f,
                    0f,
                    scrollRect.width -
                        20f,
                    contentHeight
                )
            );

        float y = 0f;

        foreach (WarboardBattleLogEntry entry
            in battleLog
                .AsEnumerable()
                .Reverse())
        {
            if (entry == null)
                continue;

            Rect entryRect =
                new Rect(
                    0f,
                    y,
                    scrollRect.width -
                        30f,
                    98f
                );

            DrawTintedBox(
                entryRect,
                new Color(
                    0.045f,
                    0.05f,
                    0.066f,
                    1f
                )
            );

            GUI.Label(
                new Rect(
                    10f,
                    y + 6f,
                    entryRect.width - 20f,
                    20f
                ),
                entry.Header
            );

            GUI.Label(
                new Rect(
                    10f,
                    y + 27f,
                    entryRect.width - 20f,
                    22f
                ),
                entry.Title,
                heading
            );

            GUI.Label(
                new Rect(
                    10f,
                    y + 51f,
                    entryRect.width - 20f,
                    42f
                ),
                entry.Detail,
                body
            );

            y += 106f;
        }

        GUI.EndScrollView();
    }

    private void DrawMovementCursorMeasureLabel()
    {
        if (!movementCursorMeasureActive ||
            string.IsNullOrWhiteSpace(
                movementCursorMeasureText))
        {
            return;
        }

        Vector2 mouse =
            Input.mousePosition;

        float x =
            mouse.x + 18f;

        float y =
            Screen.height -
            mouse.y +
            16f;

        float width =
            Mathf.Clamp(
                movementCursorMeasureText.Length *
                    7.2f +
                    24f,
                96f,
                320f
            );

        if (x + width >
            Screen.width - 8f)
        {
            x =
                Screen.width -
                width -
                8f;
        }

        if (y + 30f >
            Screen.height - 8f)
        {
            y =
                Screen.height -
                38f;
        }

        Rect box =
            new Rect(
                x,
                y,
                width,
                30f
            );

        DrawTintedBox(
            box,
            movementCursorMeasureLegal
            ? new Color(
                0.035f,
                0.12f,
                0.16f,
                0.96f
              )
            : new Color(
                0.22f,
                0.045f,
                0.035f,
                0.97f
              )
        );

        GUIStyle style =
            new GUIStyle(
                GUI.skin.label
            );

        style.alignment =
            TextAnchor.MiddleCenter;

        style.fontStyle =
            FontStyle.Bold;

        style.fontSize = 13;

        style.normal.textColor =
            Color.white;

        GUI.Label(
            box,
            movementCursorMeasureText,
            style
        );
    }

