            bar.x + 12f;

        GUI.Label(
            new Rect(
                leftMetaX,
                bar.y + 7f,
                100f,
                14f
            ),
            IsXcomMode
            ? "XCOM / AUTO"
            : "TRADITIONAL",
            WarboardV45Presentation
                .SubHeaderStyle
        );

        GUI.Label(
            new Rect(
                leftMetaX,
                bar.y + 24f,
                100f,
                14f
            ),
            battleSizeName.ToUpper(),
            WarboardV45Presentation
                .SubHeaderStyle
        );

        float leftX =
            bar.x + 120f;

        const float leftGap = 8f;

        if (GUI.Button(
            new Rect(
                leftX,
                bar.y + 8f,
                86f,
                34f
            ),
            "WARBOARD"))
        {
            showWarboardPanel =
                !showWarboardPanel;

            if (showWarboardPanel)
            {
                showBasicCommandsPanel = false;
                showStratagemMenu = false;
                showDatasheet = false;
                showMissionPanel = false;
                showBattleLog = false;
            }
        }

        leftX += 86f + leftGap;

        if (GUI.Button(
            new Rect(
                leftX,
                bar.y + 8f,
                80f,
                34f
            ),
            "MISSION INFO"))
        {
            // WARBOARD_V51_MISSION_INFO_TAB
            showMissionPanel =
                !showMissionPanel;

            if (showMissionPanel)
            {
                showWarboardPanel = false;
                showBasicCommandsPanel = false;
                showStratagemMenu = false;
                showDatasheet = false;
                showBattleLog = false;
            }
        }

        leftX += 80f + leftGap;

        if (GUI.Button(
            new Rect(
                leftX,
                bar.y + 8f,
                54f,
                34f
            ),
            "LOG"))
        {
            showBattleLog =
                !showBattleLog;

            if (showBattleLog)
            {
                showWarboardPanel = false;
                showBasicCommandsPanel = false;
                showStratagemMenu = false;
                showDatasheet = false;
                showMissionPanel = false;
            }
        }

        float rightX =
            bar.x + bar.width - 12f;

        if (!deploymentMode)
        {
            rightX -= 116f;

            if (GUI.Button(
                new Rect(
                    rightX,
                    bar.y + 8f,
                    116f,
                    34f
                ),
                "NEXT PHASE >",
                WarboardV45Presentation
                    .PrimaryButtonStyle))
            {
                NextPhase();
            }
        }

        if (!IsXcomMode &&
            !deploymentMode)
        {
            rightX -= 8f + 86f;

            if (GUI.Button(
                new Rect(
                    rightX,
                    bar.y + 8f,
                    86f,
                    34f
                ),
                showDiceTray
                ? "HIDE CTRL"
                : "DICE CTRL"))
            {
                showDiceTray =
                    !showDiceTray;
            }
        }

        rightX -= 8f + 104f;

        GUI.enabled =
            !deploymentMode;

        if (GUI.Button(
            new Rect(
                rightX,
                bar.y + 8f,
                104f,
                34f
            ),
            "STRATAGEMS"))
        {
            showStratagemMenu =
                !showStratagemMenu;

            showWarboardPanel = false;
            showBasicCommandsPanel = false;
            showDatasheet = false;
            showMissionPanel = false;
            showBattleLog = false;
        }

        GUI.enabled = true;

        rightX -= 8f + 96f;

        if (GUI.Button(
            new Rect(
                rightX,
                bar.y + 8f,
                96f,
                34f
            ),
            "COMMANDS"))
        {
            showBasicCommandsPanel =
                !showBasicCommandsPanel;

            if (showBasicCommandsPanel)
            {
                showWarboardPanel = false;
                showStratagemMenu = false;
                showDatasheet = false;
                showMissionPanel = false;
                showBattleLog = false;
            }
        }

        if (!deploymentMode &&
            factions.Count >= 2)
        {
            string p1 = factions[0];
            string p2 = factions[1];

            int p1Primary =
                TotalScoreType(p1, true);

            int p1Secondary =
                TotalScoreType(p1, false);

            int p2Primary =
                TotalScoreType(p2, true);

            int p2Secondary =
                TotalScoreType(p2, false);

            int p1Total =
                p1Primary +
                p1Secondary;

            int p2Total =
                p2Primary +
                p2Secondary;

            Rect scoreRect =
                new Rect(
                    (Screen.width - 620f) *
                        0.5f,
                    bar.y + 46f,
                    620f,
                    24f
                );

            DrawTintedBox(
                scoreRect,
                new Color(
                    0.025f,
                    0.040f,
                    0.060f,
                    0.97f
                )
            );

            GUIStyle scoreStyle =
                new GUIStyle(
                    GUI.skin.label
                );

            scoreStyle.alignment =
                TextAnchor.MiddleCenter;

            scoreStyle.fontStyle =
                FontStyle.Bold;

            scoreStyle.fontSize = 12;

            GUI.Label(
                scoreRect,
                DisplayFactionName(p1).ToUpper() +
                "  " +
                p1Total +
                " VP   P" +
                p1Primary +
                " / S" +
                p1Secondary +
                "   " +
                GetCommandPoints(p1) +
                " CP     ||     " +
                DisplayFactionName(p2).ToUpper() +
                "  " +
                p2Total +
                " VP   P" +
                p2Primary +
                " / S" +
                p2Secondary +
                "   " +
                GetCommandPoints(p2) +
                " CP",
                scoreStyle
            );
        }
    }




