    private void DrawDeploymentPanel()
    {
        float width =
            Mathf.Min(
                900f,
                Screen.width -
                    48f
            );

        float height =
            Mathf.Min(
                370f,
                Screen.height -
                    110f
            );

        Rect panel =
            new Rect(
                (Screen.width -
                 width) *
                    0.5f,
                70f,
                width,
                height
            );
        // WARBOARD_V45_3_DEPLOYMENT_PANEL_LAYOUT
        panel.width =
            Mathf.Min(
                Screen.width - 40f,
                Mathf.Max(
                    panel.width,
                    900f
                )
            );

        panel.height =
            Mathf.Max(
                panel.height,
                360f
            );

        panel.x =
            Mathf.Max(
                20f,
                (Screen.width -
                    panel.width) * 0.5f
            );
        // WARBOARD_V45_2_CENTERED_DEPLOYMENT_PANEL
        panel.x = Mathf.Max(12f, (Screen.width - panel.width) * 0.5f);

        // Fully opaque during deployment so world-space wound labels and
        // miniature highlights cannot visually leak through the menu.
        DrawTintedBox(
            panel,
            new Color(
                0.028f,
                0.032f,
                0.043f,
                1.0f
            )
        );

        Color accent =
            FactionColor(
                activeFaction
            );

        DrawTintedBox(
            new Rect(
                panel.x,
                panel.y,
                panel.width,
                3f
            ),
            accent
        );

        GUIStyle heading =
            new GUIStyle(
                GUI.skin.label
            );

        heading.fontSize = 18;
        heading.fontStyle =
            FontStyle.Bold;

        GUI.Label(
            new Rect(
                panel.x + 18f,
                panel.y + 14f,
                panel.width - 36f,
                26f
            ),
            ActiveFactionDisplayName() +
            " DEPLOYMENT",
            heading
        );

        GUIStyle muted =
            new GUIStyle(
                GUI.skin.label
            );

        muted.fontSize = 12;
        muted.wordWrap = true;

        string instruction =
            "Place the selected unit wholly inside the " +
            (activeMissionBattlefield != null
                ? activeMissionBattlefield
                    .DisplayName +
                  " " +
                  (FactionUsesAttackerZone(
                       activeFaction)
                      ? "ATTACKER"
                      : "DEFENDER") +
                  " deployment zone"
                : "deployment zone") +
            ", or send it to Reserves.";

        GUI.Label(
            new Rect(
                panel.x + 18f,
                panel.y + 43f,
                panel.width - 36f,
                34f
            ),
            instruction,
            muted
        );

        float contentY =
            panel.y + 82f;

        float leftWidth =
            Mathf.Min(
                390f,
                panel.width *
                    0.46f
            );

        float gap = 18f;

        Rect rosterOuter =
            new Rect(
                panel.x + 18f,
                contentY,
                leftWidth,
                205f
            );

        DrawTintedBox(
            rosterOuter,
            new Color(
                0.045f,
                0.05f,
                0.064f,
                1.0f
            )
        );

        GUI.Label(
            new Rect(
                rosterOuter.x + 10f,
                rosterOuter.y + 8f,
                rosterOuter.width - 20f,
                20f
            ),
            "DEPLOYMENT ORDER"
        );

        List<SquadController> undeployed =
            UndeployedUnitsForFaction(
                activeFaction
            );

        Rect rosterScrollRect =
            new Rect(
                rosterOuter.x + 8f,
                rosterOuter.y + 31f,
                rosterOuter.width - 16f,
                rosterOuter.height - 39f
            );

        float rosterHeight =
            Mathf.Max(
                rosterScrollRect.height - 4f,
                undeployed.Count *
                    34f
            );

        deploymentRosterScroll =
            GUI.BeginScrollView(
                rosterScrollRect,
                deploymentRosterScroll,
                new Rect(
                    0f,
                    0f,
                    rosterScrollRect.width -
                        20f,
                    rosterHeight
                )
            );

        float rosterY = 0f;

        foreach (SquadController squad
            in undeployed)
        {
            bool selected =
                squad ==
                currentDeploymentSquad;

            string suffix =
                squad.IsLeaderUnit
                ? "  [LEADER]"
                : (squad.HasDeepStrike
                    ? "  [DEEP STRIKE]"
                    : "");

            string label =
                (selected ? ">  " : "") +
                squad.DisplayName +
                suffix;

            if (GUI.Button(
                new Rect(
                    0f,
                    rosterY,
                    rosterScrollRect.width -
                        24f,
                    28f
                ),
                label))
            {
                ChooseDeploymentSquad(
                    squad
                );
            }

            rosterY += 34f;
        }

        GUI.EndScrollView();

        Rect detail =
            new Rect(
                rosterOuter.x +
                    rosterOuter.width +
                    gap,
                contentY,
                panel.x +
                    panel.width -
                    18f -
                    (rosterOuter.x +
                     rosterOuter.width +
                     gap),
                205f
            );

        DrawTintedBox(
            detail,
            new Color(
                0.045f,
                0.05f,
                0.064f,
                1.0f
            )
        );

        string selectedName =
            currentDeploymentSquad != null
            ? currentDeploymentSquad.DisplayName
            : "No unit selected";

        GUI.Label(
            new Rect(
                detail.x + 14f,
                detail.y + 12f,
                detail.width - 28f,
                28f
            ),
            selectedName,
            heading
        );

        if (currentDeploymentSquad != null)
        {
            string reserveType =
                currentDeploymentSquad
                    .HasDeepStrike
                ? "Deep Strike"
                : "Strategic Reserves";

            GUI.Label(
                new Rect(
                    detail.x + 14f,
                    detail.y + 47f,
                    detail.width - 28f,
                    58f
                ),
                "Models: " +
                currentDeploymentSquad
                    .StartingModels +
                "\n" +
                currentDeploymentSquad
                    .LeaderSummary() +
                "\nReserve: " +
                reserveType,
                muted
            );
        }

        GUI.enabled =
            currentDeploymentSquad != null;

        if (GUI.Button(
            new Rect(
                detail.x + 14f,
                detail.y + 116f,
                Mathf.Min(
                    185f,
                    detail.width - 28f
                ),
                32f
            ),
            "SEND TO RESERVES"))
        {
            SendCurrentDeploymentToReserves();
        }

        GUI.enabled = true;

        if (currentDeploymentSquad != null &&
            currentDeploymentSquad.IsLeaderUnit)
        {
            List<SquadController> attachTargets =
                CompatibleDeploymentBodyguards();

            SquadController chosenBodyguard =
                CurrentDeploymentBodyguardTarget();

            float attachX =
                detail.x + 208f;

            float attachWidth =
                Mathf.Max(
                    120f,
                    detail.x +
                        detail.width -
                        14f -
                        attachX
                );

            GUI.enabled =
                chosenBodyguard != null;

            if (GUI.Button(
                new Rect(
                    attachX,
                    detail.y + 116f,
                    attachWidth,
                    32f
                ),
                chosenBodyguard != null
                ? "ATTACH: " +
                  chosenBodyguard.DisplayName
                : "NO BODYGUARD"))
            {
                AttachCurrentLeader();
            }

            GUI.enabled = true;

            if (attachTargets.Count > 1)
            {
                if (GUI.Button(
                    new Rect(
                        attachX,
                        detail.y + 156f,
                        attachWidth,
                        28f
                    ),
                    "NEXT BODYGUARD  " +
                    (deploymentBodyguardChoiceIndex + 1) +
                    "/" +
                    attachTargets.Count))
                {
                    CycleDeploymentBodyguardTarget();
                }
            }
        }

        Rect statusPanel =
            new Rect(
                panel.x + 18f,
                panel.y +
                    panel.height -
                    64f,
                panel.width - 36f,
                46f
            );

        DrawTintedBox(
            statusPanel,
            new Color(
                0.055f,
                0.06f,
                0.075f,
                1.0f
            )
        );

        GUIStyle statusStyle =
            new GUIStyle(
                GUI.skin.label
            );

        statusStyle.wordWrap = true;
        statusStyle.alignment =
            TextAnchor.MiddleLeft;
        statusStyle.fontSize = 12;

        GUI.Label(
            new Rect(
                statusPanel.x + 12f,
                statusPanel.y + 5f,
                statusPanel.width - 24f,
                statusPanel.height - 10f
            ),
            status,
            statusStyle
        );
    }

