            return;

        bool visible =
            traditionalFirstTurnPending ||
            traditionalNumericPromptPending ||
            traditionalAdvancePending ||
            traditionalChargePending ||
            traditionalBattleShockPending ||
            traditionalReanimationPending;

        if (!visible)
            return;

        float width =
            Mathf.Min(
                560f,
                Screen.width - 40f
            );

        float height =
            traditionalReanimationPending
            ? 410f
            : 225f;

        Rect panel =
            new Rect(
                18f,
                116f,
                width,
                height
            );

        DrawTintedBox(
            panel,
            new Color(
                0.025f,
                0.032f,
                0.046f,
                0.985f
            )
        );

        GUIStyle title =
            new GUIStyle(
                GUI.skin.label
            );

        title.fontSize = 18;
        title.fontStyle =
            FontStyle.Bold;

        GUIStyle wrap =
            new GUIStyle(
                GUI.skin.label
            );

        wrap.wordWrap = true;
        wrap.fontSize = 12;

        if (traditionalFirstTurnPending &&
            factions.Count >= 2)
        {
            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 12f,
                    panel.width - 32f,
                    28f
                ),
                "TRADITIONAL  -  FIRST-TURN ROLL-OFF",
                title
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 46f,
                    panel.width - 32f,
                    58f
                ),
                "Roll one D6 for each player in the free tray. Resolve ties/rerolls yourselves, then tell Warboard only who won.",
                wrap
            );

            if (GUI.Button(
                new Rect(
                    panel.x + 16f,
                    panel.y + 122f,
                    240f,
                    46f
                ),
                DisplayFactionName(
                    factions[0]
                ) +
                " WON"))
            {
                CompleteTraditionalFirstTurnRollOff(
                    0
                );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 272f,
                    panel.y + 122f,
                    240f,
                    46f
                ),
                DisplayFactionName(
                    factions[1]
                ) +
                " WON"))
            {
                CompleteTraditionalFirstTurnRollOff(
                    1
                );
            }

            return;
        }

        if (traditionalNumericPromptPending)
        {
            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 12f,
                    panel.width - 32f,
                    28f
                ),
                traditionalNumericTitle,
                title
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 46f,
                    panel.width - 32f,
                    62f
                ),
                traditionalNumericText +
                "\nResolve the dice/rerolls yourself. Enter only the final value Warboard needs.",
                wrap
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 116f,
                    150f,
                    28f
                ),
                "FINAL: " +
                traditionalNumericValue,
                title
            );

            if (GUI.Button(
                new Rect(
                    panel.x + 150f,
                    panel.y + 112f,
                    54f,
                    32f
                ),
                "-1"))
            {
                traditionalNumericValue =
                    Mathf.Clamp(
                        traditionalNumericValue - 1,
                        traditionalNumericMin,
                        traditionalNumericMax
                    );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 210f,
                    panel.y + 112f,
                    54f,
                    32f
                ),
                "+1"))
            {
                traditionalNumericValue =
                    Mathf.Clamp(
                        traditionalNumericValue + 1,
                        traditionalNumericMin,
                        traditionalNumericMax
                    );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 16f,
                    panel.y + 162f,
                    170f,
                    38f
                ),
                "APPLY FINAL VALUE"))
            {
                CompleteTraditionalNumericPrompt();
            }

            if (traditionalNumericCancel != null &&
                GUI.Button(
                    new Rect(
                        panel.x + 198f,
                        panel.y + 162f,
                        120f,
                        38f
                    ),
                    "CANCEL"))
            {
                CancelTraditionalNumericPrompt();
            }

            return;
        }

        if (traditionalAdvancePending &&
            traditionalAdvanceUnit != null)
        {
            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 12f,
                    panel.width - 32f,
                    28f
                ),
                "TRADITIONAL  -  ADVANCE",
                title
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 46f,
                    panel.width - 32f,
                    54f
                ),
                traditionalAdvanceUnit.DisplayName +
                "\nRoll the Advance D6 yourself. Warboard will not inspect the dice or offer rerolls. Enter only the final bonus you are using.",
                wrap
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 112f,
                    120f,
                    28f
                ),
                "FINAL: +" +
                traditionalAdvanceResult,
                title
            );

            if (GUI.Button(
                new Rect(
                    panel.x + 150f,
                    panel.y + 108f,
                    54f,
                    32f
                ),
                "-1"))
            {
                traditionalAdvanceResult =
                    Mathf.Clamp(
                        traditionalAdvanceResult - 1,
                        1,
                        6
                    );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 210f,
                    panel.y + 108f,
                    54f,
                    32f
                ),
                "+1"))
            {
                traditionalAdvanceResult =
                    Mathf.Clamp(
                        traditionalAdvanceResult + 1,
                        1,
                        6
                    );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 16f,
                    panel.y + 158f,
                    170f,
                    38f
                ),
                "APPLY RESULT"))
            {
                CompleteTraditionalAdvance();
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 196f,
                    panel.y + 158f,
                    120f,
                    38f
                ),
                "CANCEL"))
            {
                CancelTraditionalAdvance();
            }

            return;
        }

        // WARBOARD_V51_TRADITIONAL_CHARGE_PROMPT
        if (traditionalChargePending &&
            traditionalChargeAttacker != null)
        {
            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 12f,
                    panel.width - 32f,
                    28f
                ),
                "TRADITIONAL  -  CHARGE",
                title
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 46f,
                    panel.width - 32f,
                    58f
                ),
                traditionalChargeAttacker.DisplayName +
                (traditionalChargeTarget != null
                    ? "  ->  " +
                      traditionalChargeTarget.DisplayName
                    : "  |  choose target(s) after this roll") +
                "\nRoll 2D6 yourself and apply any tabletop rerolls yourself. Enter only the final total.",
                wrap
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 112f,
                    140f,
                    28f
                ),
                "FINAL: " +
                traditionalChargeResult,
                title
            );

            if (GUI.Button(
                new Rect(
                    panel.x + 150f,
                    panel.y + 108f,
                    54f,
                    32f
                ),
                "-1"))
            {
                traditionalChargeResult =
                    Mathf.Clamp(
                        traditionalChargeResult - 1,
                        2,
                        12
                    );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 210f,
                    panel.y + 108f,
                    54f,
                    32f
                ),
                "+1"))
            {
                traditionalChargeResult =
                    Mathf.Clamp(
                        traditionalChargeResult + 1,
                        2,
                        12
                    );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 16f,
                    panel.y + 158f,
                    190f,
                    38f
                ),
                "APPLY CHARGE TOTAL"))
            {
                CompleteTraditionalCharge();
            }

            return;
        }

        if (traditionalBattleShockPending &&
            traditionalBattleShockUnit != null)
        {
            int leadership =
                EffectiveLeadership(
                    traditionalBattleShockUnit
                );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 12f,
                    panel.width - 32f,
                    28f
                ),
                "BATTLE-SHOCK TEST REQUIRED",
                title
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 46f,
                    panel.width - 32f,
                    78f
                ),
                traditionalBattleShockUnit.DisplayName +
                "  |  Leadership " +
                leadership +
                "+\nRoll 2D6 yourself and resolve every tabletop modifier/reroll yourself. Warboard only needs the final state.",
                wrap
            );

            if (GUI.Button(
                new Rect(
                    panel.x + 16f,
                    panel.y + 142f,
                    170f,
                    42f
                ),
                "MARK PASS"))
            {
                CompleteTraditionalBattleShock(
                    true
                );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 198f,
                    panel.y + 142f,
                    170f,
                    42f
                ),
                "MARK FAIL"))
            {
                CompleteTraditionalBattleShock(
                    false
                );
            }

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 190f,
                    panel.width - 32f,
                    24f
                ),
                "FAIL applies the ice-blue Battle-shock state. PASS clears it.",
                wrap
            );

            return;
        }

        if (traditionalReanimationPending)
        {
            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 12f,
                    panel.width - 32f,
                    28f
                ),
                "REANIMATION PROTOCOLS  -  MANUAL",
                title
            );

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 44f,
                    panel.width - 32f,
                    48f
                ),
                "Roll and resolve Reanimation entirely yourself. Warboard only edits the unit state you explicitly request below.",
                wrap
            );

            if (traditionalReanimationUnits.Count == 0 ||
                traditionalReanimationUnit == null)
            {
                if (GUI.Button(
                    new Rect(
                        panel.x + 16f,
                        panel.y + 104f,
                        180f,
                        38f
                    ),
                    "DONE REANIMATION"))
                {
                    FinishTraditionalReanimation();
                }

                return;
            }

            int currentIndex =
                traditionalReanimationUnits
                    .IndexOf(
                        traditionalReanimationUnit
                    );

            if (GUI.Button(
                new Rect(
                    panel.x + 16f,
                    panel.y + 98f,
                    42f,
                    30f
                ),
                "<"))
            {
                int index =
                    (currentIndex - 1 +
                     traditionalReanimationUnits.Count) %
                    traditionalReanimationUnits.Count;

                SelectTraditionalReanimationUnit(
                    traditionalReanimationUnits[
                        index
                    ]
                );
            }

            GUI.Label(
                new Rect(
                    panel.x + 66f,
                    panel.y + 101f,
                    panel.width - 132f,
                    28f
                ),
                traditionalReanimationUnit.DisplayName +
                "  (" +
                (currentIndex + 1) +
                "/" +
                traditionalReanimationUnits.Count +
                ")",
                title
            );

            if (GUI.Button(
                new Rect(
                    panel.x +
                        panel.width -
                        58f,
                    panel.y + 98f,
                    42f,
                    30f
                ),
                ">"))
            {
                int index =
                    (currentIndex + 1) %
                    traditionalReanimationUnits.Count;

                SelectTraditionalReanimationUnit(
                    traditionalReanimationUnits[
                        index
                    ]
                );
            }

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 140f,
                    panel.width - 32f,
                    38f
                ),
                "Living " +
                traditionalReanimationUnit.LivingModels +
                "/" +
                traditionalReanimationUnit.StartingModels +
                "  |  Click a wounded living model on the battlefield to heal it.",
                wrap
            );

            if (GUI.Button(
                new Rect(
                    panel.x + 16f,
                    panel.y + 184f,
                    180f,
                    36f
                ),
                "HEAL SELECTED +1"))
            {
                TraditionalHealSelectedReanimationWound();
            }

            List<ModelToken> dead =
                TraditionalReanimationDestroyedModels();

            if (dead.Count > 0)
            {
                traditionalReanimationDeadIndex =
                    Mathf.Clamp(
                        traditionalReanimationDeadIndex,
                        0,
                        dead.Count - 1
                    );

                ModelToken returning =
                    dead[
                        traditionalReanimationDeadIndex
                    ];

                if (GUI.Button(
                    new Rect(
                        panel.x + 16f,
                        panel.y + 234f,
                        42f,
                        30f
                    ),
                    "<"))
                {
                    CycleTraditionalReanimationDeadModel(
                        -1
                    );
                }

                GUI.Label(
                    new Rect(
                        panel.x + 66f,
                        panel.y + 238f,
                        panel.width - 252f,
                        26f
                    ),
                    "Return: " +
                    returning.RoleName +
                    " (" +
                    (traditionalReanimationDeadIndex + 1) +
                    "/" +
                    dead.Count +
                    ")"
                );

                if (GUI.Button(
                    new Rect(
                        panel.x +
                            panel.width -
                            184f,
                        panel.y + 232f,
                        42f,
                        30f
                    ),
                    ">"))
                {
                    CycleTraditionalReanimationDeadModel(
                        1
                    );
                }

                if (GUI.Button(
                    new Rect(
                        panel.x +
                            panel.width -
                            136f,
                        panel.y + 232f,
                        120f,
                        32f
                    ),
                    "RETURN 1W"))
                {
                    TraditionalReturnSelectedReanimationModel();
                }
            }
            else
            {
                GUI.Label(
                    new Rect(
                        panel.x + 16f,
                        panel.y + 236f,
                        panel.width - 32f,
                        28f
                    ),
                    "No destroyed models remain in this unit."
                );
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 16f,
                    panel.y + 288f,
                    180f,
                    38f
                ),
                "DONE THIS UNIT"))
            {
                CompleteTraditionalReanimationUnit();
            }

            if (GUI.Button(
                new Rect(
                    panel.x + 210f,
                    panel.y + 288f,
                    180f,
                    38f
                ),
                "DONE ALL"))
            {
                FinishTraditionalReanimation();
            }

            GUI.Label(
                new Rect(
                    panel.x + 16f,
                    panel.y + 338f,
                    panel.width - 32f,
                    54f
                ),
                "Warboard does not track Reanimation points in Traditional mode. Only press HEAL / RETURN when your manually resolved tabletop result permits it.",
                wrap
            );
        }
    }

    private void DrawTraditionalRuleAlertPanel()
    {
        if (IsXcomMode ||
            !traditionalRuleAlertPending)
        {
            return;
        }

        float width =
            Mathf.Min(
                600f,
                Screen.width - 40f
            );

        Rect panel =
            new Rect(
                18f,
                Mathf.Min(
                    540f,
                    Screen.height - 210f
                ),
                width,
                180f
            );

        DrawTintedBox(
            panel,
            new Color(
                0.09f,
                0.045f,
                0.035f,
                0.985f
            )
        );

        GUIStyle title =
            new GUIStyle(
                GUI.skin.label
            );

        title.fontSize = 18;
        title.fontStyle =
            FontStyle.Bold;

        GUIStyle wrap =
            new GUIStyle(
                GUI.skin.label
