                    150f,
                    34f
                ),
                "SHOW DICE"))
            {
                OpenTraditionalDicePrompt(
                    traditionalRuleAlertSuggestedDice
                );
            }
        }
    }

    private void DrawContextActionBar()
    {
        Rect bar =
            new Rect(
                12f,
                62f,
                Mathf.Min(
                    Screen.width - 24f,
                    1120f
                ),
                42f
            );

        DrawTintedBox(
            bar,
            new Color(
                0.035f,
                0.04f,
                0.055f,
                0.90f
            )
        );

        float x =
            bar.x + 10f;

        DrawCore11ContextControls(bar, ref x);

        if (selectedSquad != null)
        {
            GUI.Label(
                new Rect(
                    x,
                    bar.y + 10f,
                    240f,
                    24f
                ),
                selectedSquad.DisplayName
            );

            x += 245f;
        }
        else
        {
            GUI.Label(
                new Rect(
                    x,
                    bar.y + 10f,
                    180f,
                    24f
                ),
                "No unit selected"
            );

            x += 185f;
        }

        if (!IsXcomMode)
        {
            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    112f,
                    30f
                ),
                manualWoundEditMode
                ? "WOUNDS: ON"
                : "WOUND EDIT"))
            {
                manualWoundEditMode =
                    !manualWoundEditMode;

                if (manualWoundEditMode)
                    manualRestoreEditMode = false;

                pendingTraditionalRemovalCandidate = null;

                status =
                    manualWoundEditMode
                    ? "MANUAL WOUNDS: click any model, friendly or enemy, then use -1 / +1 / REMOVE."
                    : "Manual wound editing disabled.";
            }

            x += 119f;

            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    122f,
                    30f
                ),
                manualRestoreEditMode
                ? "RESTORE: ON"
                : "RESTORE EDIT"))
            {
                manualRestoreEditMode =
                    !manualRestoreEditMode;

                if (manualRestoreEditMode)
                    manualWoundEditMode = false;

                manualRestoreDeadIndex = 0;
                pendingTraditionalRemovalCandidate = null;

                status =
                    manualRestoreEditMode
                    ? "MANUAL RESTORE: select a living model/unit, then choose which destroyed model to return."
                    : "Manual restore editing disabled.";
            }

            x += 129f;

            if (manualRestoreEditMode &&
                selectedSquad != null)
            {
                List<ModelToken> restoreCandidates =
                    TraditionalRestoreCandidates();

                if (restoreCandidates.Count > 0)
                {
                    manualRestoreDeadIndex =
                        Mathf.Clamp(
                            manualRestoreDeadIndex,
                            0,
                            restoreCandidates.Count - 1
                        );

                    ModelToken candidate =
                        restoreCandidates[
                            manualRestoreDeadIndex
                        ];

                    if (GUI.Button(
                        new Rect(
                            x,
                            bar.y + 6f,
                            36f,
                            30f
                        ),
                        "<"))
                    {
                        CycleTraditionalRestoreCandidate(-1);
                    }

                    x += 40f;

                    GUI.Label(
                        new Rect(
                            x,
                            bar.y + 10f,
                            140f,
                            24f
                        ),
                        candidate.RoleName +
                        " " +
                        (manualRestoreDeadIndex + 1) +
                        "/" +
                        restoreCandidates.Count
                    );

                    x += 145f;

                    if (GUI.Button(
                        new Rect(
                            x,
                            bar.y + 6f,
                            36f,
                            30f
                        ),
                        ">"))
                    {
                        CycleTraditionalRestoreCandidate(1);
                    }

                    x += 40f;

                    if (GUI.Button(
                        new Rect(
                            x,
                            bar.y + 6f,
                            92f,
                            30f
                        ),
                        "RETURN 1W"))
                    {
                        TraditionalRestoreCurrentModel(false);
                    }

                    x += 98f;

                    if (GUI.Button(
                        new Rect(
                            x,
                            bar.y + 6f,
                            104f,
                            30f
                        ),
                        "RETURN FULL"))
                    {
                        TraditionalRestoreCurrentModel(true);
                    }

                    x += 110f;
                }
                else
                {
                    GUI.Label(
                        new Rect(
                            x,
                            bar.y + 10f,
                            130f,
                            24f
                        ),
                        "No dead models"
                    );

                    x += 135f;
                }
            }

            if (manualWoundEditMode &&
                selectedModel != null &&
                selectedModel.IsAlive)
            {
                GUI.Label(
                    new Rect(
                        x,
                        bar.y + 10f,
                        72f,
                        24f
                    ),
                    selectedModel.CurrentWounds +
                    "/" +
                    selectedModel.MaxWounds +
                    " W"
                );

                x += 76f;

                if (GUI.Button(
                    new Rect(
                        x,
                        bar.y + 6f,
                        48f,
                        30f
                    ),
                    "-1"))
                {
                    TraditionalAdjustSelectedWounds(-1);

                    if (selectedModel == null ||
                        !selectedModel.IsAlive)
                    {
                        GUI.enabled = true;
                        return;
                    }
                }

                x += 52f;

                GUI.enabled =
                    selectedModel.CurrentWounds <
                    selectedModel.MaxWounds;

                if (GUI.Button(
                    new Rect(
                        x,
                        bar.y + 6f,
                        48f,
                        30f
                    ),
                    "+1"))
                {
                    TraditionalAdjustSelectedWounds(1);
                }

                GUI.enabled = true;
                x += 52f;

                if (pendingTraditionalRemovalCandidate ==
                    selectedModel)
                {
                    if (GUI.Button(
                        new Rect(
                            x,
                            bar.y + 6f,
                            126f,
                            30f
                        ),
                        "REMOVE ANYWAY"))
                    {
                        ConfirmTraditionalModelRemoval(
                            selectedModel
                        );

                        GUI.enabled = true;
                        return;
                    }

                    x += 133f;
                }
                else
                {
                    if (GUI.Button(
                        new Rect(
                            x,
                            bar.y + 6f,
                            82f,
                            30f
                        ),
                        "REMOVE"))
                    {
                        TryTraditionalRemoveSelectedModel();

                        GUI.enabled = true;
                        return;
                    }

                    x += 89f;
                }
            }
        }

        if (phase == Phase.Move &&
            selectedSquad != null)
        {
            GUI.enabled =
                !selectedSquad.HasMoved &&
                !selectedSquad.HasAdvanced &&
                !IsEngaged(
                    selectedSquad
                );

            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    105f,
                    30f
                ),
                "ADVANCE"))
            {
                TryDeclareAdvance();
            }

            GUI.enabled = true;
            x += 112f;
        }

        if (phase == Phase.Command &&
            selectedSquad != null)
        {
            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    150f,
                    30f
                ),
                "COMMAND ABILITIES"))
            {
                TryOpenCommandAbilities();
            }

            x += 158f;
        }

        if (phase == Phase.Move)
        {
            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    135f,
                    30f
                ),
                ActiveFactionReserves().Count > 0
                ? "RESERVES"
                : "NO RESERVES"))
            {
                CycleReservePlacement();
            }

            x += 142f;
        }

        if (phase == Phase.Move &&
            selectedSquad != null &&
            factionRules != null &&
            UnitHasBattleFocusRules(
                selectedSquad
            ))
        {
            int bf =
                TotalBattleFocusTokens(
                    selectedSquad.FactionId
                );

            GUI.enabled =
                !selectedSquad.HasMoved &&
                !selectedSquad.AgileManoeuvreUsedThisPhase &&
                bf > 0;

            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    128f,
                    30f
                ),
                "SWIFT AS WIND"))
            {
                TryUseSwiftAsTheWind();
            }

            x += 135f;

            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    128f,
                    30f
                ),
                "FLITTING"))
            {
                TryUseFlittingShadows();
            }

            x += 135f;

            GUI.enabled =
                !selectedSquad.AgileManoeuvreUsedThisPhase &&
                selectedSquad.HasAdvanced &&
                selectedSquad.HasKeyword(
                    "vehicle") &&
                bf > 0;

            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    118f,
                    30f
                ),
                "STAR ENGINES"))
            {
                TryUseStarEngines();
            }

            GUI.enabled = true;
        }

        if (phase == Phase.Shoot &&
            selectedSquad != null)
        {
            if (selectedModel != null)
            {
                if (GUI.Button(
                    new Rect(
                        x,
                        bar.y + 6f,
                        120f,
                        30f
                    ),
                    "DONE MODEL"))
                {
                    CompleteSelectedModelShooting();
                }

                x += 127f;
            }

            if (GUI.Button(
                new Rect(
                    x,
                    bar.y + 6f,
                    110f,
                    30f
                ),
                "DONE UNIT"))
            {
                CompleteSelectedUnitShooting();
            }

            x += 117f;
        }

        if (phase == Phase.Shoot &&
            selectedSquad != null &&
            missionSystem != null)
        {
            MissionActionDefinition definition =
                missionSystem.PrimaryAction(
                    selectedSquad.FactionId
                );

            if (definition != null)
            {
                string reason;

                GUI.enabled =
                    missionSystem
                        .CanStartMissionAction(
                            selectedSquad,
                            out reason
                        );

                if (GUI.Button(
                    new Rect(
                        x,
                        bar.y + 6f,
                        168f,
                        30f
                    ),
                    SelectedMissionActionButtonText()))
                {
                    TryBeginSelectedMissionAction();
                }

                GUI.enabled = true;
                x += 175f;
            }
        }

        if (phase == Phase.Fight)
        {
            DrawFight11ContextControls(bar, ref x);
        }
    }

    private void DrawStatusToast()
    {
        if (string.IsNullOrWhiteSpace(
            status))
        {
            return;
        }

        float width =
            Mathf.Min(
                760f,
                Screen.width - 40f
            );

        Rect panel =
            new Rect(
                (Screen.width -
                 width) *
                    0.5f,
                Screen.height - 66f,
                width,
                46f
            );

        DrawTintedBox(
            panel,
            new Color(
                0.035f,
                0.04f,
                0.055f,
                0.90f
            )
        );

        GUIStyle style =
            new GUIStyle(
                GUI.skin.label
            );

        style.alignment =
            TextAnchor.MiddleCenter;

        GUI.Label(
            new Rect(
                panel.x + 12f,
                panel.y + 6f,
                panel.width - 24f,
                panel.height - 12f
            ),
            status,
            style
        );
    }

    private void DrawTintedBox(
        Rect rect,
        Color color)
    {
        Color previous =
            GUI.color;

        GUI.color = color;

        GUI.Box(
            rect,
            GUIContent.none
        );

        GUI.color = previous;
    }

}
